def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching with recursive backtracking for handling
    literal characters, '.', '*', and '+' in the pattern.
    """

    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx == len(pattern):
            return False

        current_match = t_idx < len(text) and (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.')

        if p_idx + 1 < len(pattern):
            if pattern[p_idx + 1] == '*':
                return (is_match(p_idx + 2, t_idx) or 
                        (current_match and is_match(p_idx, t_idx + 1)))
            elif pattern[p_idx + 1] == '+':
                return current_match and (is_match(p_idx, t_idx + 1) or is_match(p_idx + 2, t_idx))

        return current_match and is_match(p_idx + 1, t_idx + 1)

    return is_match(0, 0)

def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching using a dynamic programming approach to handle
    literal characters, '.', '*', and '+' in the pattern.
    """

    m, n = len(text), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if pattern[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j - 1] == text[i - 1] or pattern[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] and (text[i - 1] == pattern[j - 2] or pattern[j - 2] == '.'))
            elif pattern[j - 1] == '+':
                dp[i][j] = (dp[i - 1][j] and (text[i - 1] == pattern[j - 2] or pattern[j - 2] == '.')) or (i > 1 and dp[i - 1][j - 2])

    return dp[m][n]

