def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching using an iterative approach with a stack to manage
    state transitions for handling literal characters, '.', '*', and '+' in the pattern.
    """

    stack = [(0, 0)]
    while stack:
        p_idx, t_idx = stack.pop()

        if p_idx == len(pattern) and t_idx == len(text):
            return True

        if p_idx < len(pattern) and t_idx < len(text):
            current_match = (text[t_idx] == pattern[p_idx] or pattern[p_idx] == '.')
            if p_idx + 1 < len(pattern):
                if pattern[p_idx + 1] == '*':
                    stack.append((p_idx + 2, t_idx))  # Match zero occurrences
                    if current_match:
                        stack.append((p_idx, t_idx + 1))  # Match one occurrence
                elif pattern[p_idx + 1] == '+':
                    if current_match:
                        stack.append((p_idx, t_idx + 1))  # Match one occurrence
                    continue  # Cannot match here since '+' requires at least one match
            if current_match:
                stack.append((p_idx + 1, t_idx + 1))  # Move both pointers

        elif p_idx < len(pattern) and (pattern[p_idx] == '*' or pattern[p_idx] == '+'):
            continue  # Skip these characters since they need a match

    return False

def match(pattern: str, text: str) -> bool:
    """
    Implements regex matching using a finite state machine (FSM) approach to handle
    literal characters, '.', '*', and '+' in the pattern.
    """

    def build_nfa(pattern: str):
        nfa = []
        state_count = 0

        for char in pattern:
            if char == '*':
                nfa[state_count - 1].append(state_count)  # Loop back to previous state
            elif char == '+':
                nfa.append([state_count - 1])  # This assumes `+` follows at least one occurrence
                state_count += 1
            else:
                nfa.append([])
                nfa[state_count].append(state_count + 1)  # Go to the next state
                state_count += 1

        return nfa

    def matches(nfa, text):
        current_states = {0}  # Start state

        for char in text:
            next_states = set()
            for state in current_states:
                if state < len(nfa):  # Ensure we are within bounds of the NFA states
                    for target in nfa[state]:
                        if pattern[target - 1] == char or pattern[target - 1] == '.':
                            next_states.add(target)
            current_states = next_states

        return len(current_states) > 0 and max(current_states) == len(nfa)

    nfa = build_nfa(pattern)
    return matches(nfa, text)
